import {baseScenario,sampleScenarios,normalizeScenario,validateScenario,budgetEstimate,scenarioWarnings,ENGINE_VERSION} from './model.js';

const $=s=>document.querySelector(s),escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,d=0)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:d}).format(v||0);
const pct=v=>`${(100*(v||0)).toFixed(1)}%`;
const deep=structuredClone;
const storageKey='retirement-readiness-lab-sites-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(storageKey));}catch{}
const state={scenarios:Array.isArray(saved?.scenarios)&&saved.scenarios.length?saved.scenarios.map(normalizeScenario):sampleScenarios(),selectedId:saved?.selectedId||'base-plan',view:'dashboard',results:new Map(),labResults:null,decision:null,busy:false,message:'',advancedOpen:false,allocationOpen:false};
if(!state.scenarios.some(s=>s.id===state.selectedId))state.selectedId=state.scenarios[0].id;
function current(){return state.scenarios.find(s=>s.id===state.selectedId)||state.scenarios[0];}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({scenarios:state.scenarios,selectedId:state.selectedId}));}catch{state.message='Browser storage is unavailable. Export a backup to keep your scenarios.';}}
function result(){return state.results.get(current().id);}
function setMessage(message){state.message=message;render();}
function currentViewLabel(){return {dashboard:'Overview',setup:'Assumptions',budget:'Budget',scenarios:'Scenarios',lab:'Scenario lab',results:'Results',reports:'Reports & backup'}[state.view];}
function pageHead(title,detail='',actions=''){return `<div class="page-head"><div><p class="kicker">${escapeHTML(currentViewLabel())}</p><h1>${escapeHTML(title)}</h1><p>${escapeHTML(detail)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function card(title,content,extra=''){return `<section class="card ${extra}"><h2>${escapeHTML(title)}</h2>${content}</section>`;}
function info(label,value){return `<div class="info-row"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong></div>`;}
function tag(value){const c=value==='AtRisk'?'risk':value==='Watch'?'watch':'';return `<span class="tag ${c}">${escapeHTML(value)}</span>`;}
function notice(){return state.message?`<div class="notice ${state.message.startsWith('Error')?'error':'good'}" role="status">${escapeHTML(state.message)}</div>`:'';}
function resultSummary(r){if(!r)return `<div class="notice">Run this scenario to see its readiness estimate and outcome range.</div>`;return `<div class="grid three">${card('Median ending balance',`<div class="metric-value">${money(r.medianEndingBalance)}</div><div class="metric-sub">Across ${r.provenance.simulationCount.toLocaleString()} simulated paths</div>`)}${card('Downside balance',`<div class="metric-value">${money(r.pessimisticEndingBalance)}</div><div class="metric-sub">10th percentile at the projection end</div>`)}${card('Median failure age',`<div class="metric-value">${r.medianFailureAge??'—'}</div><div class="metric-sub">${r.medianFailureAge===null?'No simulated paths ran out of funds':'Among paths that ran out of funds'}</div>`)}</div>`;}
function chartSVG(bands,key='median'){if(!bands?.length)return '<p class="muted">Run a scenario to see its projected balance path.</p>';const w=720,h=240,pad=26,max=Math.max(1,...bands.map(x=>x.optimistic)),x=i=>pad+i*(w-pad*2)/Math.max(1,bands.length-1),y=v=>h-pad-Math.max(0,v)/max*(h-pad*2),line=(field)=>bands.map((b,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(b[field]).toFixed(1)}`).join(' '),area=line('optimistic')+bands.slice().reverse().map((b,j)=>` L${x(bands.length-1-j).toFixed(1)},${y(b.pessimistic).toFixed(1)}`).join('')+' Z';return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Projected balance by age, including tenth to ninetieth percentile range"><path d="${area}" fill="#dcefe5"/><path d="${line('optimistic')}" fill="none" stroke="#96c6ac" stroke-width="2"/><path d="${line('pessimistic')}" fill="none" stroke="#96c6ac" stroke-width="2"/><path d="${line(key)}" fill="none" stroke="#176b5b" stroke-width="3" stroke-linecap="round"/><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#a7bcb0"/><text x="${pad}" y="${h-4}" fill="#647a6c" font-size="13">Age ${bands[0].age}</text><text x="${w-pad}" y="${h-4}" text-anchor="end" fill="#647a6c" font-size="13">Age ${bands.at(-1).age}</text></svg><p class="chart-caption">Center line: median balance. Shaded area: 10th to 90th percentile.</p>`;}
function dashboard(){const s=current(),r=result(),notes=scenarioWarnings(s);const prob=r?.successProbability??0;return `${pageHead('Plan overview',`${s.name} · retire at ${s.household.retirementAge} · ${money(s.spending.annualBaseSpending)} annual base spending`)}${notice()}<div class="stack"><div class="grid two"><section class="card feature-card"><div><div class="label">Readiness estimate</div><div class="huge">${r?pct(prob):'—'}</div><p>${r?'Share of modeled lifetimes without a portfolio shortfall.':'Run a simulation to assess this plan.'}</p></div><div class="ring" style="--value:${r?Math.round(prob*100):0}%"><span>${r?'Projected paths':'Awaiting run'}</span></div></section><div class="grid">${card('Plan at a glance',`<div class="info-list">${info('Starting assets',money(Object.values(s.accounts).reduce((a,b)=>a+b,0)))}${info('Annual spending',money(s.spending.annualBaseSpending))}${info('Social Security claim age',s.socialSecurity.claimAge)}${info('Pre-Medicare premium',`${money(s.healthcare.preMedicareMonthlyPremium)} / adult / month`)}</div>`)}${r?card('Next useful test',`<p>${escapeHTML(r.riskBreakdown.recommendedNextTest)}</p><button class="secondary" data-view="lab">Open scenario lab</button>`):''}</div></div>${resultSummary(r)}${notes.length?card('Planning notes',`<ul class="warning-list">${notes.map(n=>`<li>${escapeHTML(n)}</li>`).join('')}</ul>`):''}<div class="split">${card('Balance path',chartSVG(r?.balanceBands))}${card('Risk scan',r?`<div class="info-list">${['market','spending','taxes','healthcare','longevity'].map(k=>`<div class="info-row"><span>${escapeHTML(k[0].toUpperCase()+k.slice(1))}</span>${tag(r.riskBreakdown[k])}</div>`).join('')}</div><p class="sticky-note">Primary watch item: ${escapeHTML(r.riskBreakdown.primaryRisk)}.</p>`:'<p class="muted">Run the plan to identify its main planning risks.</p>')}</div></div>`;}
const schema=[
  ['Household & retirement',[['Current age','household.currentAge','number'],['Retirement age','household.retirementAge','number'],['Maximum modeling age','household.targetEndAge','number'],['Filing status','household.filingStatus','select','Single|Married|HeadOfHousehold'],['Your longevity table','household.gender','select','Male|Female'],['Spouse age','household.spouseCurrentAge','number'],['Spouse longevity table','household.spouseGender','select','Male|Female']]],
  ['Accounts & spending',[['Pre-tax savings','accounts.pretax','money'],['Roth savings','accounts.roth','money'],['Taxable savings','accounts.taxable','money'],['Cash reserve','accounts.cash','money'],['Annual base spending','spending.annualBaseSpending','money'],['Spending path','spending.spendingPathModel','select','EmpiricalAgeDecline|Flat'],['General inflation average %','spending.generalInflationMean','percent'],['General inflation volatility %','spending.generalInflationStdDev','percent'],['Cut spending if portfolio halves %','spending.lowPortfolioSpendingReduction','percent']]],
  ['Income & Social Security',[['Annual benefit at age 67','socialSecurity.annualBenefitAt67','money'],['Claim age','socialSecurity.claimAge','number'],['Spouse claim age','socialSecurity.spouseClaimAge','number'],['Guaranteed annual income','guaranteedIncome.annualIncome','money'],['Income start age','guaranteedIncome.startAge','number'],['Income annual increase %','guaranteedIncome.annualIncrease','percent'],['Survivor benefit %','guaranteedIncome.survivorPercent','percent']]],
  ['Housing & healthcare',[['Mortgage payment / month','mortgage.monthlyPayment','money'],['Mortgage years left','mortgage.yearsLeft','number'],['Mortgage months left','mortgage.monthsLeft','number'],['Mortgage balance','mortgage.currentBalance','money'],['Home value','home.currentValue','money'],['Rent / month','rent.monthlyRent','money'],['Pre-Medicare premium / adult / month','healthcare.preMedicareMonthlyPremium','money'],['Healthcare inflation average %','healthcare.healthcareInflationMean','percent'],['Healthcare inflation volatility %','healthcare.healthcareInflationStdDev','percent'],['Include Medicare premiums','healthcare.includeMedicarePremiums','checkbox'],['Long-term care risk','longTermCare.enabled','checkbox'],['Long-term care cost / year','longTermCare.annualCost','money'],['Long-term care duration / years','longTermCare.averageDurationYears','number']]],
  ['Market & withdrawal strategy',[['Pre-retirement return average %','market.preRetirementMeanReturn','percent'],['Pre-retirement return volatility %','market.preRetirementStdDev','percent'],['Stock return average %','market.stockMeanReturn','percent'],['Stock return volatility %','market.stockStdDev','percent'],['Bond return average %','market.bondMeanReturn','percent'],['Bond return volatility %','market.bondStdDev','percent'],['Roth conversions','rothConversion.enabled','checkbox'],['Conversion tax bracket cap %','rothConversion.marginalRateCap','percent'],['Use cash in market drawdowns','withdrawalStrategy.useCashReserveDuringDrawdowns','checkbox'],['Drawdown trigger %','withdrawalStrategy.drawdownTrigger','percent'],['Early withdrawal penalty','withdrawalStrategy.applyEarlyWithdrawalPenalty','checkbox'],['Rule of 55 eligible','withdrawalStrategy.ruleOf55Eligible','checkbox'],['72(t) / SEPP eligible','withdrawalStrategy.seppEligible','checkbox'],['Simulation paths','numberOfSimulations','number'],['Random seed','seed','number']]],
  ['Stock allocation by portfolio size',[['Under 30× spending %','postRetirementAllocation.stockUnder30x','percent'],['30–35× spending %','postRetirementAllocation.stock30xTo35x','percent'],['35–40× spending %','postRetirementAllocation.stock35xTo40x','percent'],['40–45× spending %','postRetirementAllocation.stock40xTo45x','percent'],['45–50× spending %','postRetirementAllocation.stock45xTo50x','percent'],['50× or more %','postRetirementAllocation.stock50xOrMore','percent']]]
];
const assumptionHelp={
  'accounts.pretax':'Traditional 401(k), IRA, and similar tax-deferred balances. The model treats withdrawals from this balance as taxable income.',
  'accounts.roth':'Roth retirement account balances. The model treats withdrawals from this balance as tax-free.',
  'accounts.taxable':'Brokerage investments outside retirement accounts. The model includes them in invested savings and can draw on them for spending.',
  'accounts.cash':'Cash reserve kept apart from invested savings. It can help cover withdrawals during modeled market declines.',
  'spending.annualBaseSpending':'Your yearly living costs in today’s dollars. Costs entered separately below, such as rent, mortgage, and healthcare premiums, are added on top.',
  'spending.generalInflationMean':'The average yearly increase assumed for general living and housing costs.',
  'socialSecurity.claimAge':'Age when the model starts your Social Security benefit. It adjusts the age-67 estimate above for this claiming age.',
  'guaranteedIncome.startAge':'Age when the pension or annuity income begins in the simulation.',
  'mortgage.monthlyPayment':'Monthly mortgage payment added separately to living costs while the loan remains. Enter 0 if there is no mortgage.',
  'mortgage.yearsLeft':'Full years remaining on the mortgage. Add any extra months in the next field.',
  'mortgage.monthsLeft':'Extra months remaining beyond the full years above, from 0 through 11.',
  'mortgage.currentBalance':'Estimated unpaid mortgage principal. The model uses it to calculate home-sale proceeds if savings run out.',
  'rent.monthlyRent':'Monthly rent added separately to living costs during retirement. Leave at 0 if you are not renting.',
  'healthcare.healthcareInflationMean':'Average yearly growth assumed for healthcare premiums and long-term care costs.',
  'longTermCare.annualCost':'Annual cost per person during a modeled long-term care episode, before future healthcare inflation.',
  'longTermCare.averageDurationYears':'Number of years a modeled care episode lasts before the person’s death when long-term care occurs.',
  'market.stockMeanReturn':'Average yearly return assumed for the stock share of invested savings after retirement.',
  'market.bondMeanReturn':'Average yearly return assumed for the bond share of invested savings after retirement.',
  'market.bondStdDev':'How much modeled bond returns vary around their average after retirement.',
  'household.gender':'Select the mortality rates used to draw your lifespan in each simulation. This does not change your filing status.',
  'household.spouseGender':'Select the mortality rates used to draw your spouse’s lifespan in married simulations.',
  'spending.spendingPathModel':'Age-based decline gradually lowers base spending from ages 65 to 85. Flat keeps base spending level before inflation.',
  'spending.generalInflationStdDev':'Controls how much inflation varies around the average in simulated months. Higher values make future costs less predictable.',
  'spending.lowPortfolioSpendingReduction':'The model reduces base spending by this percentage while total savings are below half their value at retirement.',
  'socialSecurity.annualBenefitAt67':'Enter an annual Social Security estimate at age 67 in today’s dollars. The model adjusts it for the claim age below and applies its own future inflation.',
  'socialSecurity.spouseClaimAge':'The spouse’s modeled claiming age. Spousal or survivor payments may begin later if other conditions are not met.',
  'guaranteedIncome.annualIncome':'Annual pension or annuity income, separate from Social Security. It begins at the income start age.',
  'guaranteedIncome.annualIncrease':'Yearly growth rate for the pension or annuity amount entered above.',
  'guaranteedIncome.survivorPercent':'For a married plan, the share of guaranteed income retained by the spouse after the primary person dies.',
  'home.currentValue':'The home is not counted as spendable savings initially. If the portfolio runs out, the model sells it, pays the remaining mortgage, and adds rent.',
  'healthcare.preMedicareMonthlyPremium':'Monthly healthcare premium for each retired adult younger than 65. The model grows this cost with healthcare inflation.',
  'healthcare.healthcareInflationStdDev':'Controls how much healthcare cost growth varies around its average in simulated months.',
  'healthcare.includeMedicarePremiums':'Adds modeled Medicare premiums from age 65, including higher-income surcharges when applicable.',
  'longTermCare.enabled':'Adds a chance of long-term care costs near the end of each modeled life, using the cost and duration below.',
  'market.preRetirementMeanReturn':'Average annual investment return before retirement. This strongly affects the assets available at retirement.',
  'market.preRetirementStdDev':'How much pre-retirement investment returns vary around their average. Higher values widen the range of outcomes.',
  'market.stockStdDev':'How much modeled stock returns vary around their average after retirement.',
  'rothConversion.enabled':'Moves some pre-tax savings into Roth savings at year end and pays the estimated conversion tax from the portfolio.',
  'rothConversion.marginalRateCap':'Limits modeled Roth conversions to this tax bracket. It applies only when Roth conversions are on.',
  'withdrawalStrategy.useCashReserveDuringDrawdowns':'Uses the cash reserve before invested accounts when the modeled monthly portfolio return falls below the trigger.',
  'withdrawalStrategy.drawdownTrigger':'The monthly portfolio return that activates cash-first withdrawals. For example, -1% means a month below -1%.',
  'withdrawalStrategy.applyEarlyWithdrawalPenalty':'Adds a modeled 10% penalty to applicable early retirement-account withdrawals before age 59½, subject to the Rule of 55 setting.',
  'withdrawalStrategy.ruleOf55Eligible':'In this model, removes that early withdrawal penalty when retirement age is at least 55. Verify your actual eligibility separately.',
  'withdrawalStrategy.seppEligible':'Models a series of pre-tax distributions using the app’s life-expectancy formula. Verify the actual 72(t) rules before relying on it.',
  'numberOfSimulations':'Number of simulated lifetimes. More paths make the readiness estimate steadier but take longer to run.',
  'seed':'Reuses the same random sequence so scenario comparisons can be repeated. It does not make an outcome more likely.'
};
function helpHTML(path,label){const tip=assumptionHelp[path];if(!tip)return '';const id='help-'+path.replaceAll('.','-');return `<span class="help"><button type="button" class="help-trigger" aria-label="Explain ${escapeHTML(label)}" aria-describedby="${id}" aria-expanded="false">?</button><span class="help-popover" id="${id}" role="tooltip">${escapeHTML(tip)}</span></span>`;}
const spouseFieldPaths=new Set(['household.spouseCurrentAge','household.spouseGender','socialSecurity.spouseClaimAge','guaranteedIncome.survivorPercent']);
function visibleFields(s,fields){return s.household.filingStatus==='Married'?fields:fields.filter(([,path])=>!spouseFieldPaths.has(path));}
function getPath(obj,path){return path.split('.').reduce((v,k)=>v[k],obj);}
function setPath(obj,path,value){const keys=path.split('.');const last=keys.pop();keys.reduce((v,k)=>v[k],obj)[last]=value;}
function fieldHTML(s,[label,path,type,options]){
  const value=getPath(s,path),id='f-'+path.replaceAll('.','-'),help=helpHTML(path,label);
  if(type==='checkbox')return `<div class="field checkbox"><input id="${id}" type="checkbox" data-field="${path}" data-type="${type}" ${value?'checked':''}><label for="${id}">${escapeHTML(label)}</label>${help}</div>`;
  const heading=`<div class="field-label"><label for="${id}">${escapeHTML(label)}</label>${help}</div>`;
  if(type==='select')return `<div class="field">${heading}<select id="${id}" data-field="${path}" data-type="${type}">${options.split('|').map(opt=>`<option value="${opt}" ${opt===value?'selected':''}>${escapeHTML(path.endsWith('gender')||path.endsWith('Gender')?opt+' mortality rates':opt==='HeadOfHousehold'?'Head of household':opt==='EmpiricalAgeDecline'?'Empirical age decline':opt)}</option>`).join('')}</select></div>`;
  const resource=path==='socialSecurity.annualBenefitAt67'?`<div class="field-resource"><a href="https://www.ssa.gov/myaccount/" target="_blank" rel="noopener noreferrer">Find your estimate at my Social Security ↗</a><small>Choose today’s dollars if offered; multiply the age-67 monthly estimate by 12.</small></div>`:'';
  return `<div class="field">${heading}<input id="${id}" type="number" inputmode="decimal" step="${type==='number'?1:'any'}" data-field="${path}" data-type="${type}" value="${escapeHTML(type==='percent'?Number((value*100).toPrecision(10)):value)}">${resource}</div>`;
}
function setup(){
  const s=current(),limitField=schema[0][1].find(([,path])=>path==='household.targetEndAge');
  const sections=schema.map(([title,fields])=>{
    const shown=visibleFields(s,fields).filter(([,path])=>path!=='household.targetEndAge');
    const inputs=`<div class="fields">${shown.map(f=>fieldHTML(s,f)).join('')}</div>`;
    if(title==='Stock allocation by portfolio size'){
      return `<details id="allocation-settings" class="card advanced-settings" ${state.allocationOpen?'open':''}><summary>${escapeHTML(title)}</summary><p class="form-note allocation-note">The app compares invested savings with one year of modeled costs. A 30× balance means invested savings equal 30 times that yearly amount; it is not a guarantee of 30 years of funding. Each percentage is the stock share; the rest is bonds.</p>${inputs}</details>`;
    }
    const note=title==='Household & retirement'?'<p class="form-note">Longevity tables guide mortality estimates. Spouse settings appear when filing status is Married.</p>':'';
    return card(title,inputs+note);
  }).join('');
  return `${pageHead('Plan assumptions','Adjust the inputs, then run the plan to refresh its results.',`<button class="secondary" data-action="reset-assumptions">Restore sample values</button>`)}${notice()}<div class="stack">${sections}<details id="advanced-model" class="card advanced-settings" ${state.advancedOpen?'open':''}><summary>Advanced model settings</summary><p class="form-note">The maximum modeling age caps the simulation. It is not a predicted lifespan; each modeled lifetime uses mortality rates.</p><div class="fields">${fieldHTML(s,limitField)}</div></details><p class="form-note">Percent fields accept values such as 2.3 for 2.3%. Changes save in this browser. Results refresh when you run the simulation.</p></div>`;
}
function budget(){const s=current(),b=s.budget,estimate=budgetEstimate(b);return `${pageHead('Build an annual budget','Use recent monthly spending to estimate base spending for the plan.',`<button class="primary" data-action="apply-budget">Use ${money(estimate)} in plan</button>`)}${notice()}<div class="stack">${card('Annual fixed costs',`<div class="fields">${[['Property taxes','annualPropertyTaxes'],['Home insurance','annualHomeInsurance'],['Auto insurance','annualAutoInsurance']].map(([label,key])=>`<div class="field"><label for="budget-${key}">${label}</label><input id="budget-${key}" type="number" min="0" step="any" data-budget="${key}" value="${escapeHTML(b[key])}"></div>`).join('')}</div>`)}${card('Monthly spending',`<div class="section-heading"><p class="form-note">Add each month once. Enter the total checking bills, credit card bills, and cash withdrawals for that month.</p><button class="secondary" data-action="add-month">Add month</button></div>${b.monthlyBudgets.length?b.monthlyBudgets.map((m,i)=>`<div class="budget-month"><label>Month<input type="month" data-month="${i}" data-part="month" value="${escapeHTML(m.month)}"></label><label>Checking bills<input type="number" min="0" step="any" data-month="${i}" data-part="checking" value="${escapeHTML(m.checkingSavingsBills.reduce((x,v)=>x+Number(v.monthlyAmount),0))}"></label><label>Credit card bills<input type="number" min="0" step="any" data-month="${i}" data-part="credit" value="${escapeHTML(m.creditCardBills.reduce((x,v)=>x+Number(v.monthlyAmount),0))}"></label><label>Cash / ATM<input type="number" min="0" step="any" data-month="${i}" data-part="cashAndAtmWithdrawals" value="${escapeHTML(m.cashAndAtmWithdrawals)}"></label><button class="danger" data-action="remove-month" data-index="${i}">Remove</button></div>`).join(''):'<p class="muted">No monthly budgets entered yet.</p>'}`)}${card('Budget estimate',`<div class="metric-value">${money(estimate)}</div><p class="form-note">Annual fixed costs plus 12 times the average of up to 12 entered months.</p><p class="form-note">${b.isAppliedToAnnualBaseSpending?'This estimate is currently applied to annual base spending.':'This estimate has not been applied to the plan.'}</p>`)}</div>`;}
function scenarios(){return `${pageHead('Saved scenarios','Compare plans without losing the assumptions behind each one.',`<button class="primary" data-action="new-scenario">Duplicate current plan</button>`)}${notice()}${card('Plans',state.scenarios.map(s=>`<div class="scenario-row"><div><h3>${escapeHTML(s.name)} ${s.id===state.selectedId?'<span class="tag">Selected</span>':''}</h3><p>Retire at ${s.household.retirementAge} · ${money(s.spending.annualBaseSpending)} annual spending · ${money(Object.values(s.accounts).reduce((a,b)=>a+b,0))} assets</p></div><div class="actions"><button class="secondary" data-action="select-scenario" data-id="${escapeHTML(s.id)}">Open</button><button class="subtle" data-action="rename-scenario" data-id="${escapeHTML(s.id)}">Rename</button><button class="danger" data-action="delete-scenario" data-id="${escapeHTML(s.id)}" ${state.scenarios.length===1?'disabled':''}>Delete</button></div></div>`).join(''))}`;}
const labVariants=[['Retire 2 years later',s=>s.household.retirementAge+=2],['Spend 5% less',s=>s.spending.annualBaseSpending*=.95],['Claim Social Security at 70',s=>s.socialSecurity.claimAge=70],['Higher healthcare costs',s=>{s.healthcare.preMedicareMonthlyPremium*=1.25;s.healthcare.healthcareInflationMean=Math.min(.20,s.healthcare.healthcareInflationMean+.01);}],['Use Roth conversions',s=>{s.rothConversion.enabled=true;s.rothConversion.marginalRateCap=.22;}],['Larger cash reserve strategy',s=>{s.withdrawalStrategy.useCashReserveDuringDrawdowns=true;s.withdrawalStrategy.drawdownTrigger=-.01;}]];
function lab(){return `${pageHead('Scenario lab','Change one assumption at a time and compare each outcome against the same starting plan.',`<button class="primary" data-action="run-lab" ${state.busy?'disabled':''}>Run comparisons</button><button class="secondary" data-action="run-decision" ${state.busy?'disabled':''}>Find age & spending targets</button>`)}${notice()}${state.decision?card('Planning targets',`<div class="grid two"><div><span class="metric-label">Earliest age at ${pct(state.decision.targetReadiness)} readiness</span><div class="metric-value">${state.decision.earliestRetirementAge??'No age found'}</div><p class="form-note">Search through age 70 with ${state.decision.simulationCount} paths per age.</p></div><div><span class="metric-label">Annual spending at ${pct(state.decision.targetReadiness)} readiness</span><div class="metric-value">${state.decision.safeAnnualSpending===null?'No amount found':money(state.decision.safeAnnualSpending)}</div><p class="form-note">Rounded down to $500; rerun the full plan before making decisions.</p></div></div>`):''}${state.labResults?card('Readiness comparison',`<div class="comparison-row"><strong>Scenario</strong><strong>Readiness</strong><strong>Median ending</strong></div>${state.labResults.map(r=>`<div class="comparison-row"><div><strong>${escapeHTML(r.label)}</strong>${r.error?`<div class="muted">${escapeHTML(r.error)}</div>`:''}</div><strong>${r.result?pct(r.result.successProbability):'—'}</strong><strong>${r.result?money(r.result.medianEndingBalance):'—'}</strong></div>`).join('')}<p class="form-note">Each comparison uses ${Math.min(current().numberOfSimulations,150)} paths with the same seed for reproducible screening. Run the full plan for final results.</p>`):card('Quick comparisons',`<p class="form-note">The lab tests retirement timing, spending, claiming age, healthcare costs, Roth conversions, and cash use.</p><ul class="warning-list">${labVariants.map(x=>`<li>${escapeHTML(x[0])}</li>`).join('')}</ul>`)}`;}
function results(){const r=result();return `${pageHead('Simulation results','Examine outcomes, uncertainty, and the assumptions used to calculate them.')}${notice()}${!r?'<div class="notice">Run the selected scenario to view its results.</div>':`<div class="stack">${resultSummary(r)}<div class="split">${card('Projected portfolio balance',chartSVG(r.balanceBands))}${card('Readiness',`<div class="metric-value">${pct(r.successProbability)}</div><div class="bar"><span style="width:${Math.round(100*r.successProbability)}%"></span></div><p class="form-note">${r.provenance.simulationCount} simulated lifetimes · seed ${r.provenance.randomSeed}</p><p>${escapeHTML(r.riskBreakdown.recommendedNextTest)}</p>`)}</div>${card('Portfolio survival by age',`<div class="table-wrap"><table><thead><tr><th>Age</th><th>Share without shortfall</th><th>Share alive</th></tr></thead><tbody>${r.notFailedByAge.filter((_,i)=>i%5===0||i===r.notFailedByAge.length-1).map(p=>`<tr><td>${p.age}</td><td>${pct(p.notFailedShare)}</td><td>${pct(p.aliveShare)}</td></tr>`).join('')}</tbody></table></div>`)}${card('Balance bands by age',`<div class="table-wrap"><table><thead><tr><th>Age</th><th>10th percentile</th><th>Median</th><th>90th percentile</th></tr></thead><tbody>${r.balanceBands.filter((_,i)=>i%5===0||i===r.balanceBands.length-1).map(b=>`<tr><td>${b.age}</td><td>${money(b.pessimistic)}</td><td>${money(b.median)}</td><td>${money(b.optimistic)}</td></tr>`).join('')}</tbody></table></div>`)}${card('Failure ages',r.failureAgeBuckets.length?`<div class="info-list">${r.failureAgeBuckets.map(b=>info(`Ages ${b.label}`,`${b.count} paths · ${pct(b.shareOfFailures)} of failures`)).join('')}</div>`:'<p class="muted">No simulated paths ran out of funds.</p>')}</div>`}`;}
function reportText(s,r){const precisePct=v=>`${Number((v*100).toPrecision(12))}%`;const lines=[`RETIREMENT READINESS LAB — ${s.name}`,`Generated ${new Date().toLocaleString()}`,`Calculation engine: ${r?.provenance.engineVersion||ENGINE_VERSION}`,`Simulation paths: ${s.numberOfSimulations}; seed: ${s.seed}`,'',`Current age: ${s.household.currentAge}; retirement age: ${s.household.retirementAge}`,`Filing status: ${s.household.filingStatus}`,`Starting pre-tax: ${money(s.accounts.pretax,2)}; Roth: ${money(s.accounts.roth,2)}; taxable: ${money(s.accounts.taxable,2)}; cash: ${money(s.accounts.cash,2)}`,`Annual base spending: ${money(s.spending.annualBaseSpending,2)}`,`General inflation: ${precisePct(s.spending.generalInflationMean)} ± ${precisePct(s.spending.generalInflationStdDev)}`,`Social Security benefit at 67: ${money(s.socialSecurity.annualBenefitAt67,2)}; claim age: ${s.socialSecurity.claimAge}`,`Pre-Medicare monthly premium: ${money(s.healthcare.preMedicareMonthlyPremium,2)}`,`Long-term care: ${s.longTermCare.enabled?'included':'excluded'}`,`Roth conversions: ${s.rothConversion.enabled?'enabled':'disabled'}`,''];lines.push('ALL ASSUMPTIONS');for(const [section,fields] of schema){lines.push(section+':');for(const [label,path,type] of visibleFields(s,fields)){const value=getPath(s,path);lines.push(`  ${label}: ${type==='percent'?precisePct(value):type==='money'?money(value,2):type==='checkbox'?(value?'Yes':'No'):value}`);}}lines.push(`Budget months: ${s.budget.monthlyBudgets.length}`,`Property taxes: ${money(s.budget.annualPropertyTaxes,2)}; home insurance: ${money(s.budget.annualHomeInsurance,2)}; auto insurance: ${money(s.budget.annualAutoInsurance,2)}`,'');if(r)lines.push(`Readiness: ${pct(r.successProbability)}`,`Median ending balance: ${money(r.medianEndingBalance)}`,`10th / 90th percentile: ${money(r.pessimisticEndingBalance)} / ${money(r.optimisticEndingBalance)}`,`Median failure age: ${r.medianFailureAge??'none'}`,`Primary risk: ${r.riskBreakdown.primaryRisk}`,`Next useful test: ${r.riskBreakdown.recommendedNextTest}`);else lines.push('Run the scenario to include results.');lines.push('','Educational planning estimate, not financial advice. Data is stored locally in this browser.');return lines.join('\n');}
function reports(){const text=reportText(current(),result());return `${pageHead('Reports & backup','Export the current plan or keep a backup of all scenarios.',`<button class="secondary" data-action="print">Print / save PDF</button>`)}${notice()}<div class="grid two">${card('Current plan report',`<div class="actions"><button class="secondary" data-action="download-report">Download text</button><button class="secondary" data-action="copy-report">Copy report</button></div><pre class="report-text">${escapeHTML(text)}</pre>`)}${card('Scenario backup',`<p>Save all plans in one JSON file or restore a previous backup.</p><div class="actions"><button class="primary" data-action="export-backup">Export JSON</button><button class="secondary" data-action="import-backup">Import JSON</button></div><p class="form-note">Imports web backups or Android scenario JSON arrays. Import replaces the plans saved in this browser, so export a backup first if you want to keep them.</p>`)}</div>`;}
function render(){const details=$('#advanced-model');if(details)state.advancedOpen=details.open;const allocation=$('#allocation-settings');if(allocation)state.allocationOpen=allocation.open;const select=$('#scenario-select');select.innerHTML=state.scenarios.map(s=>`<option value="${escapeHTML(s.id)}" ${s.id===state.selectedId?'selected':''}>${escapeHTML(s.name)}</option>`).join('');$('#run-button').disabled=state.busy;$('#run-button').textContent=state.busy?'Calculating…':'Run simulation';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#main').innerHTML=({dashboard,setup,budget,scenarios,lab,results,reports}[state.view]||dashboard)();}
function runWorker(s,task='simulation'){return new Promise((resolve,reject)=>{const worker=new Worker('./worker.js',{type:'module'});worker.onmessage=e=>{worker.terminate();e.data.type==='result'?resolve(e.data.result):reject(new Error(e.data.message));};worker.onerror=e=>{worker.terminate();reject(new Error(e.message||'Calculation failed'));};worker.postMessage({scenario:s,task});});}
async function run(){if(state.busy)return;const s=deep(current()),errors=validateScenario(s);if(errors.length){state.message='Error: '+errors.join(' ');render();return;}state.busy=true;state.message='Calculating this plan…';render();try{const r=await runWorker(s);state.results.set(s.id,r);state.message='Results updated for '+s.name+'.';}catch(e){state.message='Error: '+e.message;}finally{state.busy=false;render();}}
async function runDecision(){if(state.busy)return;state.busy=true;state.message='Finding retirement-age and spending targets…';render();try{state.decision=await runWorker(deep(current()),'decision');state.message='Planning targets ready.';}catch(e){state.message='Error: '+e.message;}finally{state.busy=false;render();}}
async function runLab(){if(state.busy)return;state.busy=true;state.labResults=[];state.message='Running scenario comparisons…';render();const base=deep(current());base.numberOfSimulations=Math.min(150,base.numberOfSimulations);const variants=[['Current plan',()=>{}],...labVariants];for(const [label,change] of variants){const s=deep(base);change(s);const errors=validateScenario(s);try{state.labResults.push({label,result:errors.length?null:await runWorker(s),error:errors.join(' ')});}catch(e){state.labResults.push({label,result:null,error:e.message});}render();}state.busy=false;state.message='Comparisons ready.';render();}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function closeHelp(except=null){for(const help of document.querySelectorAll('.help.open')){if(help===except)continue;help.classList.remove('open');help.querySelector('.help-trigger').setAttribute('aria-expanded','false');}}
document.addEventListener('click',e=>{const trigger=e.target instanceof Element?e.target.closest('.help-trigger'):null,help=trigger?.closest('.help'),wasOpen=help?.classList.contains('open');closeHelp();if(trigger&&!wasOpen){help.classList.add('open');trigger.setAttribute('aria-expanded','true');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeHelp();if(document.activeElement?.classList.contains('help-trigger'))document.activeElement.blur();}});
$('#run-button').addEventListener('click',run);
$('#scenario-select').addEventListener('change',e=>{state.selectedId=e.target.value;state.labResults=null;state.decision=null;persist();render();});
$('#navigation').addEventListener('click',e=>{const button=e.target.closest('[data-view]');if(!button)return;state.view=button.dataset.view;state.message='';render();window.scrollTo(0,0);});
$('#main').addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){state.view=nav.dataset.view;render();return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,s=current();
  if(a==='reset-assumptions'){if(!confirm('Restore sample assumptions for this scenario?'))return;const fresh=baseScenario();fresh.id=s.id;fresh.name=s.name;state.scenarios[state.scenarios.indexOf(s)]=fresh;state.results.delete(s.id);persist();setMessage('Sample assumptions restored.');}
  if(a==='new-scenario'){const copy=deep(s);copy.id='plan-'+Date.now();copy.name=s.name+' copy';state.scenarios.push(copy);state.selectedId=copy.id;state.view='setup';persist();setMessage('Scenario copied. Adjust its assumptions.');}
  if(a==='select-scenario'){state.selectedId=el.dataset.id;state.view='dashboard';persist();render();}
  if(a==='rename-scenario'){const target=state.scenarios.find(x=>x.id===el.dataset.id),name=prompt('Scenario name',target.name);if(name?.trim()){target.name=name.trim();persist();render();}}
  if(a==='delete-scenario'){if(state.scenarios.length===1||!confirm('Delete this scenario?'))return;state.scenarios=state.scenarios.filter(x=>x.id!==el.dataset.id);state.results.delete(el.dataset.id);if(state.selectedId===el.dataset.id)state.selectedId=state.scenarios[0].id;persist();render();}
  if(a==='add-month'){const month=new Date().toISOString().slice(0,7);s.budget.monthlyBudgets.push({month,checkingSavingsBills:[],creditCardBills:[],cashAndAtmWithdrawals:0});persist();render();}
  if(a==='remove-month'){s.budget.monthlyBudgets.splice(Number(el.dataset.index),1);persist();render();}
  if(a==='apply-budget'){s.spending.annualBaseSpending=budgetEstimate(s.budget);s.budget.isAppliedToAnnualBaseSpending=true;state.results.delete(s.id);persist();setMessage('Budget estimate applied. Run the plan to refresh results.');}
  if(a==='run-lab')await runLab();
  if(a==='run-decision')await runDecision();
  if(a==='download-report')download('retirement-report.txt',reportText(s,result()),'text/plain');
  if(a==='copy-report'){try{await navigator.clipboard.writeText(reportText(s,result()));setMessage('Report copied.');}catch{setMessage('Error: Clipboard access is unavailable. Download the text report instead.');}}
  if(a==='print')window.print();
  if(a==='export-backup')download('retirement-scenarios.json',JSON.stringify({format:'retirement-readiness-lab-web-v1',scenarios:state.scenarios},null,2),'application/json');
  if(a==='import-backup')$('#import-file').click();
});
$('#main').addEventListener('change',e=>{const el=e.target,s=current();if(el.dataset.field){const type=el.dataset.type,value=type==='checkbox'?el.checked:type==='select'?el.value:Number(el.value)/(type==='percent'?100:1);setPath(s,el.dataset.field,value);state.results.delete(s.id);state.labResults=null;state.decision=null;persist();state.message='Saved. Run the simulation to refresh results.';render();return;}
  if(el.dataset.budget){s.budget[el.dataset.budget]=Number(el.value);state.results.delete(s.id);persist();render();return;}
  if(el.dataset.month){const m=s.budget.monthlyBudgets[Number(el.dataset.month)],part=el.dataset.part;if(part==='month')m.month=el.value;else if(part==='cashAndAtmWithdrawals')m.cashAndAtmWithdrawals=Number(el.value);else m[part==='checking'?'checkingSavingsBills':'creditCardBills']=[{id:part,name:part==='checking'?'Checking bills':'Credit card bills',monthlyAmount:Number(el.value)}];state.results.delete(s.id);persist();render();}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text()),scenarios=Array.isArray(data)?data:data.scenarios;if(!Array.isArray(scenarios)||!scenarios.length)throw new Error('No scenarios found in the file.');const normalized=scenarios.map(normalizeScenario);for(const s of normalized){const errors=validateScenario(s);if(errors.length)throw new Error(`${s.name}: ${errors.join(' ')}`);}state.scenarios=normalized;state.selectedId=normalized[0].id;state.results.clear();state.labResults=null;persist();setMessage(`${normalized.length} scenarios imported.`);}catch(error){setMessage('Error: '+error.message);}e.target.value='';});
render();
